// PUT /ocpi/emsp/2.2/tariffs/{country_code}/{party_id}/{tariff_id}
// Crear o actualizar una Tariff completa (OCPI 2.2)
router.put('/:country_code/:party_id/:tariff_id', validateTariffPutMiddleware, async (req, res) => {
    try {
        const { country_code, party_id, tariff_id } = req.params;
        const tariffData = req.validatedTariff;

        logger.info(`📥 PUT Tariff received`, {
            country_code,
            party_id,
            tariff_id,
            timestamp: new Date().toISOString()
        });

        const exists = await tariffExists(tariff_id);

        if (exists) {
            await updateTariff(tariff_id, tariffData, party_id, country_code);
        } else {
            await createTariff(tariff_id, tariffData, party_id, country_code);
        }

        res.status(200).json({
            status_code: 1000,
            status_message: 'Success',
            timestamp: new Date().toISOString()
        });

    } catch (error) {
        logger.error(`❌ Error processing Tariff PUT: ${error.message}`, {
            error: error.message,
            stack: error.stack,
            params: req.params,
            body: req.body
        });

        res.status(500).json({
            status_code: 2000,
            status_message: `Internal server error: ${error.message}`,
            timestamp: new Date().toISOString()
        });
    }
});

// PATCH /ocpi/emsp/2.2/tariffs/{country_code}/{party_id}/{tariff_id}
// Actualizar parcialmente una Tariff (OCPI 2.2)
router.patch('/:country_code/:party_id/:tariff_id', validateTariffPatchMiddleware, async (req, res) => {
    try {
        const { sequelize } = require('../database/connection');
        const result = await processTariffPatchRequest(req.params, req.validatedTariffPatch, sequelize);

        if (result.error) {
            return res.status(result.error.status).json(result.error.json);
        }

        res.status(200).json(result.success);

    } catch (error) {
        const errorResponse = buildTariffPatchErrorResponse(error, req.params, req.body);
        res.status(errorResponse.status).json(errorResponse.json);
    }
});

module.exports = router;

const logger = require('../../utils/logger');

const {
  validateTariffExists,
  buildTariffNotFoundResponse,
  buildTariffPatchFields,
  executeTariffUpdate,
  buildTariffPatchSuccessResponse,
  buildTariffPatchErrorResponse
} = require('./tariffPatchHelpers');

/**
 * Procesa la petición PATCH de tarifa
 * @param {Object} params - Parámetros de la ruta
 * @param {Object} updateData - Datos de actualización
 * @param {Object} sequelize - Instancia de Sequelize
 * @returns {Promise<Object>} Resultado de la operación
 */
async function processTariffPatchRequest(params, updateData, sequelize) {
  const { country_code, party_id, tariff_id } = params;

  logger.info(`📥 PATCH Tariff received`, {
    country_code,
    party_id,
    tariff_id,
    updateFields: Object.keys(updateData),
    timestamp: new Date().toISOString()
  });

  const exists = await validateTariffExists(sequelize, tariff_id, country_code, party_id);
  if (!exists) {
    return { error: buildTariffNotFoundResponse() };
  }

  const { updateFields, replacements } = buildTariffPatchFields(updateData);

  if (updateFields.length === 0) {
    logger.warn(`⚠️ No fields to update for PATCH`, {
      country_code,
      party_id,
      tariff_id
    });
    return {
      error: {
        status: 400,
        json: {
          status_code: 2001,
          status_message: 'No fields to update',
          timestamp: new Date().toISOString()
        }
      }
    };
  }

  await executeTariffUpdate(sequelize, updateFields, replacements, tariff_id);

  logger.info(`✅ Tariff patched: ${tariff_id}`, {
    updatedFields: Object.keys(updateData)
  });

  return { success: buildTariffPatchSuccessResponse() };
}

module.exports = {
    processTariffPatchRequest
};

