const { URL } = require('url');

const { v4: uuidv4 } = require('uuid');

const { Credentials } = require('../../models');

const { buildRejectedCredentialsResponse } = require('./builders');

/**
 * Crea credenciales temporales para organización externa rechazada
 * @param {string} partyId - Party ID
 * @param {string} countryCode - Country code
 * @param {string} sanitizedUrl - URL sanitizada
 * @returns {Object} Credenciales temporales
 */
function createTempCredentials(partyId, countryCode, sanitizedUrl) {
  return {
    id: uuidv4(),
    token: `temp_${uuidv4().replace(/-/g, '')}`,
    url: sanitizedUrl,
    business_details: {
      name: `External Organization ${partyId}`,
      website: sanitizedUrl
    },
    party_id: partyId,
    country_code: countryCode,
    external_party_id: `${countryCode}-${partyId}`,
    valid: false,
    temp: true,
    last_updated: new Date().toISOString()
  };
}

/**
 * Maneja el caso cuando las credenciales son rechazadas
 * @param {Object} params - Parámetros de manejo
 * @param {string} params.partyId - Party ID
 * @param {string} params.countryCode - Country code
 * @param {string} params.sanitizedUrl - URL sanitizada
 * @param {Object} params.ourCredentials - Nuestras credenciales
 * @param {Object} params.res - Response object
 */
async function handleRejectedCredentials({ partyId, countryCode, sanitizedUrl, ourCredentials, res }) {
  console.log('⚠️ POST /credentials rechazado, el operador externo iniciará el handshake');

  const externalCredentials = createTempCredentials(partyId, countryCode, sanitizedUrl);

  try {
    await Credentials.create(externalCredentials);
    console.log('✅ Información de organización externa guardada (pendiente de handshake)');
  } catch (dbError) {
    console.error('❌ Error guardando información de organización externa:', dbError);
  }

  return res.status(200).json(buildRejectedCredentialsResponse(partyId, countryCode, sanitizedUrl, ourCredentials));
}

/**
 * Crea y guarda las credenciales externas exitosas
 * @param {Object} params - Parámetros de guardado
 * @param {Object} params.credentialsResponse - Respuesta de credentials
 * @param {string} params.partyId - Party ID
 * @param {string} params.countryCode - Country code
 * @param {Array} params.operatorEndpoints - Endpoints del operador
 * @param {string} params.token - Token temporal original
 */
async function saveExternalCredentials({ credentialsResponse, partyId, countryCode, operatorEndpoints, token }) {
  const externalUrl = new URL(credentialsResponse.data.data.url);
  const baseUrl = `${externalUrl.protocol}//${externalUrl.host}`;

  const cpoRole = credentialsResponse.data.data.roles?.find(role => role.role === 'CPO');
  const businessDetails = cpoRole?.business_details || {
    name: `External Organization ${partyId}`,
    website: baseUrl
  };

  const externalCredentials = {
    id: uuidv4(),
    token: credentialsResponse.data.data.token,
    url: baseUrl,
    business_details: businessDetails,
    party_id: partyId,
    country_code: countryCode,
    valid: true,
    temp: false,
    external_party_id: partyId,
    last_updated: new Date().toISOString()
  };

  console.log('🔍 Objeto externalCredentials construido:', JSON.stringify(externalCredentials, null, 2));

  if (operatorEndpoints.length > 0) {
    externalCredentials.endpoints = operatorEndpoints;
  }

  await Credentials.create(externalCredentials);

  // Invalidar token temporal si existe
  if (token !== credentialsResponse.data.token) {
    await Credentials.update(
      { valid: false },
      { where: { token } }
    );
  }
}

/**
 * Crea credenciales temporales para el handshake inicial
 * @param {Object} params - Parámetros de creación
 * @param {string} params.partyId - Party ID
 * @param {string} params.countryCode - Country code
 * @param {string} params.url - URL de la organización externa
 * @param {string} params.initialToken - Token inicial generado
 * @param {Object} params.ourCredentials - Nuestras credenciales
 * @returns {Object} Credenciales de handshake
 */
function createHandshakeCredentials({ partyId, countryCode, url, initialToken, ourCredentials }) {
  return {
    id: uuidv4(),
    token: initialToken,
    url,
    business_details: ourCredentials.business_details,
    party_id: partyId,
    country_code: countryCode,
    valid: true,
    temp: true,
    last_updated: new Date().toISOString()
  };
}

module.exports = {
    createTempCredentials,
    handleRejectedCredentials,
    saveExternalCredentials,
    createHandshakeCredentials
};

const express = require('express');
const router = express.Router();
const { v4: uuidv4 } = require('uuid');

const { Location, EVSE } = require('../models');
const emspNotificationService = require('../services/emspNotificationService');
const logger = require('../utils/logger');
const { logLocationData, logArrayData } = require('../utils/loggingUtils');

const {
  validatePaginationParams,
  buildWhereClause,
  calculatePaginationInfo,
  buildPaginationHeaders
} = require('./locations/paginationHelpers');
const { cleanLocation } = require('./locations/transformers');

/**
 * @swagger
 * /ocpi/2.2/locations:
 *   get:
 *     summary: Get OCPI locations with pagination
 *     tags: [Locations]
 *     parameters:
 *       - in: query
 *         name: country_code
 *         schema:
 *           type: string
 *         description: Filter by country code
 *       - in: query
 *         name: party_id
 *         schema:
 *           type: string
 *         description: Filter by party ID
 *       - in: query
 *         name: offset
 *         schema:
 *           type: integer
 *         description: Pagination offset (default 0)
 *       - in: query
 *         name: limit
 *         schema:
 *           type: integer
 *         description: Pagination limit (max 1000, default 25)
 *     responses:
 *       200:
 *         description: Successfully retrieved locations
 *         headers:
 *           X-Total-Count:
 *             description: Total number of locations
 *             schema:
 *               type: integer
 *           X-Limit:
 *             description: Maximum number of locations returned
 *             schema:
 *               type: integer
 *           X-Offset:
 *             description: Offset of the first location returned
 *             schema:
 *               type: integer
 *       400:
 *         description: Bad request - invalid pagination parameters
 *       500:
 *         description: Internal server error
 */
router.get('/', async (req, res) => {
  try {
    logger.ocpi('/locations', 'GET', { query: req.query });

    const { country_code, party_id, offset = 0, limit = 25 } = req.query;

    const paginationError = validatePaginationParams(offset, limit);
    if (paginationError) {
      return res.status(paginationError.status).json(paginationError.json);
    }

    const offsetInt = parseInt(offset);
    const limitInt = parseInt(limit);
    const where = buildWhereClause(country_code, party_id);

    const totalCount = await Location.count({ where });
    const locations = await queryLocationsWithEVSEs(where, offsetInt, limitInt);
    const { hasNextPage } = calculatePaginationInfo(totalCount, offsetInt, limitInt);
    const cleanedLocations = processLocationsForResponse(locations, logLocationData, logArrayData);

    const headers = buildPaginationHeaders(totalCount, limitInt, hasNextPage, req);
    res.set(headers);

    res.status(200).json({
      status_code: 1000,
      data: cleanedLocations,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error getting locations:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /ocpi/2.2/locations/{id}:
 *   get:
 *     summary: Get specific OCPI location
 *     tags: [Locations]
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: string
 */
router.get('/:id', async (req, res) => {
  try {
    logger.ocpi('/locations', 'GET_BY_ID', { id: req.params.id });

    const { id } = req.params;
    const location = await Location.findByPk(id, {
      where: { deleted_at: null }, // Solo incluir location activa
      include: [{
        model: EVSE,
        as: 'evseList',
        where: { deleted_at: null }, // Solo incluir EVSEs activos (no soft-deleted)
        required: false, // LEFT JOIN para incluir location sin EVSEs
        attributes: ['id', 'evse_id', 'status', 'capabilities', 'connectors', 'physical_reference', 'last_updated']
      }]
    });

    if (!location) {
      return res.status(404).json({
        status_code: 2004,
        status_message: 'Location not found',
        timestamp: new Date().toISOString()
      });
    }

    res.status(200).json({
      status_code: 1000,
      data: location,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error getting location:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

