const { EmspToken } = require('../../models');
const logger = require('../../utils/logger');

/**
 * Busca un token existente en la base de datos
 * @param {string} countryCode - Country code
 * @param {string} partyId - Party ID
 * @param {string} uid - Token UID
 * @returns {Promise<Object|null>} Token encontrado o null
 */
async function findToken(countryCode, partyId, uid) {
  return await EmspToken.findOne({
    where: {
      emsp_country_code: countryCode,
      emsp_party_id: partyId,
      token_uid: uid
    }
  });
}

/**
 * Prepara los datos para actualizar un token existente
 * @param {Object} tokenData - Datos del token del request
 * @param {string} countryCode - Country code
 * @param {string} partyId - Party ID
 * @param {string} uid - Token UID
 * @returns {Object} Datos para actualizar
 */
function prepareTokenUpdateData(tokenData, countryCode, partyId, uid) {
  return {
    type: tokenData.type,
    contract_id: tokenData.contract_id || `${countryCode}-${partyId}-${uid}`,
    issuer: tokenData.issuer,
    valid: tokenData.valid !== undefined ? tokenData.valid : true,
    whitelist: tokenData.whitelist || 'NEVER',
    language: tokenData.language || null,
    default_profile_type: tokenData.default_profile_type || null,
    energy_contract: tokenData.energy_contract || null,
    last_updated: new Date()
  };
}

/**
 * Prepara los datos para crear un nuevo token
 * @param {Object} tokenData - Datos del token del request
 * @param {string} countryCode - Country code
 * @param {string} partyId - Party ID
 * @param {string} uid - Token UID
 * @returns {Object} Datos para crear
 */
function prepareTokenCreateData(tokenData, countryCode, partyId, uid) {
  const tokenId = `${partyId}-${uid}`;

  return {
    id: tokenId,
    emsp_party_id: partyId,
    emsp_country_code: countryCode,
    token_uid: uid,
    type: tokenData.type,
    contract_id: tokenData.contract_id || `${countryCode}-${partyId}-${uid}`,
    issuer: tokenData.issuer,
    valid: tokenData.valid !== undefined ? tokenData.valid : true,
    whitelist: tokenData.whitelist || 'NEVER',
    language: tokenData.language || null,
    default_profile_type: tokenData.default_profile_type || null,
    energy_contract: tokenData.energy_contract || null,
    last_updated: new Date()
  };
}

/**
 * Mapea un token de la base de datos al formato OCPI 2.2
 * Maneja tanto tokens regulares (Token) como tokens EMSP (EmspToken)
 * @param {Object} token - Token de la base de datos
 * @returns {Object} Token mapeado según OCPI 2.2
 */
function mapTokenToOCPI(token) {
  // Determinar si es un token EMSP o un token regular
  const isEmspToken = token.emsp_country_code !== undefined;

  const mappedToken = {
    country_code: isEmspToken ? token.emsp_country_code : token.country_code,
    party_id: isEmspToken ? token.emsp_party_id : token.party_id,
    uid: isEmspToken ? token.token_uid : token.uid,
    type: token.type,
    contract_id: token.contract_id,
    issuer: token.issuer,
    valid: token.valid,
    whitelist: token.whitelist,
    last_updated: token.last_updated.toISOString()
  };

  // Agregar campos opcionales si existen
  if (token.visual_number) {
    mappedToken.visual_number = token.visual_number;
  }

  if (token.group_id) {
    mappedToken.group_id = token.group_id;
  }

  if (token.language) {
    mappedToken.language = token.language;
  }

  if (token.default_profile_type) {
    mappedToken.default_profile_type = token.default_profile_type;
  }

  if (token.energy_contract) {
    mappedToken.energy_contract = token.energy_contract;
  }

  return mappedToken;
}

module.exports = {
    findToken,
    prepareTokenUpdateData,
    prepareTokenCreateData,
    mapTokenToOCPI
};

const express = require('express');

const router = express.Router();
const { Op } = require('sequelize');

const { ValidationError } = require('../models');
const logger = require('../utils/logger');

/**
 * @swagger
 * /api/validation-errors:
 *   get:
 *     summary: Get validation errors
 *     tags: [Validation Errors]
 *     parameters:
 *       - in: query
 *         name: limit
 *         schema:
 *           type: integer
 *           default: 100
 *       - in: query
 *         name: offset
 *         schema:
 *           type: integer
 *           default: 0
 *       - in: query
 *         name: endpoint
 *         schema:
 *           type: string
 *       - in: query
 *         name: method
 *         schema:
 *           type: string
 */
router.get('/', async (req, res) => {
  try {
    const { limit = 100, offset = 0, endpoint, method } = req.query;

    const where = {};
    if (endpoint) where.endpoint = { [Op.like]: `%${endpoint}%` };
    if (method) where.method = method;

    const { count, rows } = await ValidationError.findAndCountAll({
      where,
      limit: Math.min(parseInt(limit), 500),
      offset: parseInt(offset),
      order: [['timestamp', 'DESC']]
    });

    res.status(200).json({
      status_code: 1000,
      data: rows,
      pagination: {
        total: count,
        limit: Math.min(parseInt(limit), 500),
        offset: parseInt(offset)
      },
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error getting validation errors:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /api/validation-errors/{id}:
 *   get:
 *     summary: Get specific validation error
 *     tags: [Validation Errors]
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 */
router.get('/:id', async (req, res) => {
  try {
    const { id } = req.params;

    const validationError = await ValidationError.findByPk(id);

    if (!validationError) {
      return res.status(404).json({
        status_code: 2004,
        status_message: 'Validation error not found',
        timestamp: new Date().toISOString()
      });
    }

    res.status(200).json({
      status_code: 1000,
      data: validationError,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error getting validation error:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /api/validation-errors:
 *   delete:
 *     summary: Delete all validation errors
 *     tags: [Validation Errors]
 */
router.delete('/', async (_req, res) => {
  try {
    const deletedCount = await ValidationError.destroy({
      where: {},
      truncate: true
    });

    logger.info(`Deleted ${deletedCount} validation errors`);

    res.status(200).json({
      status_code: 1000,
      status_message: `Successfully deleted all validation errors`,
      // eslint-disable-next-line camelcase -- Campo en snake_case según convención de API
      deleted_count: deletedCount,
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error deleting validation errors:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

/**
 * @swagger
 * /api/validation-errors/{id}:
 *   delete:
 *     summary: Delete specific validation error
 *     tags: [Validation Errors]
 *     parameters:
 *       - in: path
 *         name: id
 *         required: true
 *         schema:
 *           type: integer
 */
router.delete('/:id', async (req, res) => {
  try {
    const { id } = req.params;

    const validationError = await ValidationError.findByPk(id);

    if (!validationError) {
      return res.status(404).json({
        status_code: 2004,
        status_message: 'Validation error not found',
        timestamp: new Date().toISOString()
      });
    }

    await validationError.destroy();

    res.status(200).json({
      status_code: 1000,
      status_message: 'Validation error deleted successfully',
      timestamp: new Date().toISOString()
    });
  } catch (error) {
    logger.error('Error deleting validation error:', error);
    res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error',
      timestamp: new Date().toISOString()
    });
  }
});

module.exports = router;

