const OCPITokenService = require('../services/ocpiTokenService');
const logger = require('../utils/logger');

// Token OCPI por defecto para desarrollo (se usará solo si no hay tokens en BD)
const DEFAULT_OCPI_TOKEN = process.env.OCPI_TOKEN || 'ocpi_token_ipd_2024_secure_key';

/**
 * Middleware de autenticación OCPI
 * Valida que la petición incluya el token correcto en las cabeceras
 */
const {
  extractToken,
  validateToken,
  checkTempTokenPermission,
  buildTokenObject,
  DEFAULT_OCPI_TOKEN
} = require('./auth/authHelpers');

const authMiddleware = async (req, res, next) => {
  try {
    const providedToken = extractToken(req);

    if (!providedToken) {
      logger.warn('Authentication failed: No token provided', { 
        ip: req.ip, 
        path: req.path,
        headers: req.headers 
      });

      return res.status(401).json({
        status_code: 2001,
        status_message: 'Authentication failed: No token provided',
        timestamp: new Date().toISOString()
      });
    }

    const tokenInfo = await validateToken(providedToken);

    if (!tokenInfo && providedToken !== DEFAULT_OCPI_TOKEN) {
      logger.warn('Authentication failed: Invalid token', { 
        ip: req.ip, 
        path: req.path,
        providedToken: `${providedToken.substring(0, 10)}...`
      });

      return res.status(401).json({
        status_code: 2001,
        status_message: 'Authentication failed: Invalid token',
        timestamp: new Date().toISOString()
      });
    }

    const permissionError = checkTempTokenPermission(tokenInfo, req.originalUrl);
    if (permissionError) {
      logger.warn('Authentication failed: Temporary token not allowed for this endpoint', { 
        ip: req.ip, 
        path: req.path,
        providedToken: `${providedToken.substring(0, 10)}...`
      });

      return res.status(permissionError.status).json(permissionError.json);
    }

    req.ocpiToken = buildTokenObject(tokenInfo);

    logger.info('Authentication successful', { 
      ip: req.ip, 
      path: req.path,
      partyId: req.ocpiToken.party_id,
      countryCode: req.ocpiToken.country_code
    });

    next();
  } catch (error) {
    logger.error('Authentication error:', error);
    return res.status(500).json({
      status_code: 2000,
      status_message: 'Internal server error during authentication',
      timestamp: new Date().toISOString()
    });
  }
};

/**
 * Middleware opcional para endpoints que no requieren autenticación
 * (como health check, documentación, etc.)
 */
const optionalAuthMiddleware = async (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    const token = req.headers['ocpi-token'] || req.headers['OCPI-Token'];

    let providedToken = null;
    if (authHeader && authHeader.startsWith('Token ')) {
      providedToken = authHeader.substring(6);
    } else if (token) {
      providedToken = token;
    }

    // Si se proporciona un token, validarlo
    if (providedToken) {
      const tokenInfo = await OCPITokenService.validateToken(providedToken);

      if (!tokenInfo && providedToken !== DEFAULT_OCPI_TOKEN) {
        logger.warn('Optional authentication failed: Invalid token', { 
          ip: req.ip, 
          path: req.path 
        });

        return res.status(401).json({
          status_code: 2001,
          status_message: 'Authentication failed: Invalid token',
          timestamp: new Date().toISOString()
        });
      }

      // Si el token es válido, agregar información a la request
      if (tokenInfo) {
        req.ocpiToken = tokenInfo;
      }
    }

    // Continuar (con o sin token válido)
    next();
  } catch (error) {
    logger.error('Optional authentication error:', error);
    next(); // Continuar en caso de error
  }
};

module.exports = {
  authMiddleware,
  optionalAuthMiddleware,
  DEFAULT_OCPI_TOKEN
};

const OCPITokenService = require('../../services/ocpiTokenService');
const logger = require('../../utils/logger');

const DEFAULT_OCPI_TOKEN = process.env.OCPI_TOKEN || 'ocpi_token_ipd_2024_secure_key';

/**
 * Extrae el token de las cabeceras de la petición
 * @param {Object} req - Request object
 * @returns {string|null} Token extraído o null
 */
function extractToken(req) {
  const authHeader = req.headers.authorization;
  const token = req.headers['ocpi-token'] || req.headers['OCPI-Token'];

  if (authHeader && authHeader.startsWith('Token ')) {
    return authHeader.substring(6);
  } else if (token) {
    return token;
  }

  return null;
}

/**
 * Valida si un token temporal está permitido en el endpoint
 * @param {string} originalUrl - URL original de la petición
 * @returns {boolean} True si está permitido, false si no
 */
function isTempTokenAllowed(originalUrl) {
  const tempTokenAllowedPaths = [
    '/ocpi/versions',
    '/ocpi/cpo/2.2/details', 
    '/ocpi/cpo/2.2/credentials'
  ];

  return tempTokenAllowedPaths.some(path => originalUrl.startsWith(path));
}

/**
 * Valida el token y retorna información del token o null
 * @param {string} providedToken - Token proporcionado
 * @returns {Promise<Object|null>} Información del token o null
 */
async function validateToken(providedToken) {
  const tokenInfo = await OCPITokenService.validateToken(providedToken);

  if (!tokenInfo) {
    if (providedToken !== DEFAULT_OCPI_TOKEN) {
      return null;
    }
  }

  return tokenInfo;
}

/**
 * Verifica si el token temporal está permitido para el endpoint
 * @param {Object} tokenInfo - Información del token
 * @param {string} originalUrl - URL original de la petición
 * @returns {Object|null} Objeto con error o null si está permitido
 */
function checkTempTokenPermission(tokenInfo, originalUrl) {
  if (tokenInfo && tokenInfo.temp === true) {
    if (!isTempTokenAllowed(originalUrl)) {
      return {
        status: 403,
        json: {
          status_code: 2002,
          status_message: 'Forbidden: This endpoint requires a permanent token',
          timestamp: new Date().toISOString()
        }
      };
    }
  }

  return null;
}

/**
 * Construye el objeto de token para la request
 * @param {Object|null} tokenInfo - Información del token validado
 * @returns {Object} Objeto de token para req.ocpiToken
 */
function buildTokenObject(tokenInfo) {
  return tokenInfo || { 
    party_id: process.env.OCPI_PARTY_ID || 'IPD', 
    country_code: process.env.OCPI_COUNTRY_CODE || 'ES',
    type: 'default' 
  };
}

module.exports = {
    extractToken,
    validateToken,
    checkTempTokenPermission,
    buildTokenObject,
    DEFAULT_OCPI_TOKEN
};

const logger = require('../utils/logger');

const {
  shouldExcludePath,
  captureRequestBody,
  captureRelevantHeaders,
  logIncomingRequest,
  setupResponseInterceptors,
  handleResponseFinish
} = require('./requestLogger/helpers');

/**
 * Middleware para logging detallado de peticiones y respuestas
 * Captura payload entrante y response saliente
 */
const requestLogger = (req, res, next) => {
  const userAgent = req.get('User-Agent') || '';

  if (shouldExcludePath(req.path, userAgent)) {
    return next();
  }

  const startTime = Date.now();
  const requestBody = captureRequestBody(req.body);
  const relevantHeaders = captureRelevantHeaders(req.headers);

  logIncomingRequest(req, relevantHeaders, requestBody);

  const { responseBody, responseHeaders } = setupResponseInterceptors(res);

  res.on('finish', async () => {
    await handleResponseFinish({ req, res, startTime, relevantHeaders, requestBody, responseBody, responseHeaders });
  });

  next();
};

module.exports = requestLogger;

const logger = require('../../utils/logger');

/**
 * Verifica si una ruta debe ser excluida del logging
 * @param {string} path - Ruta de la petición
 * @param {string} userAgent - User agent de la petición
 * @returns {boolean} True si debe ser excluida, false si no
 */
function shouldExcludePath(path, userAgent) {
  // Excluir endpoints de logs para evitar bucles infinitos
  if (path === '/logs/recent' || path === '/logs/stream') {
    return true;
  }

  // Excluir peticiones del navegador (aplicación web)
  if (userAgent.includes('Mozilla') || userAgent.includes('Chrome') || userAgent.includes('Safari')) {
    return true;
  }

  // Excluir recursos estáticos
  if (path.match(/\.(css|js|png|jpg|jpeg|gif|ico|svg|woff|woff2|ttf|eot)$/)) {
    return true;
  }

  // Excluir health check
  if (path === '/health') {
    return true;
  }

  // Excluir peticiones de la interfaz web (API calls desde el frontend)
  if (path.startsWith('/api/') && userAgent.includes('Mozilla')) {
    return true;
  }

  return false;
}

/**
 * Captura el body de la petición de forma segura
 * @param {Object} body - Request body
 * @returns {Object|null} Body copiado o null
 */
function captureRequestBody(body) {
  if (body && Object.keys(body).length > 0) {
    try {
      return JSON.parse(JSON.stringify(body));
    } catch (error) {
      return null;
    }
  }
  return null;
}

/**
 * Captura headers relevantes de la petición
 * @param {Object} headers - Request headers
 * @returns {Object} Headers relevantes filtrados
 */
function captureRelevantHeaders(headers) {
  const relevantHeaders = {
    'authorization': headers.authorization ? `${headers.authorization.substring(0, 20)}...` : undefined,
    'ocpi-token': headers['ocpi-token'] ? `${headers['ocpi-token'].substring(0, 20)}...` : undefined,
    'content-type': headers['content-type'],
    'user-agent': headers['user-agent'],
    'accept': headers.accept
  };

  // Filtrar headers undefined
  Object.keys(relevantHeaders).forEach(key => {
    if (relevantHeaders[key] === undefined) {
      delete relevantHeaders[key];
    }
  });

  return relevantHeaders;
}

/**
 * Registra la petición entrante
 * @param {Object} req - Request object
 * @param {Object} relevantHeaders - Headers relevantes
 * @param {Object} requestBody - Request body capturado
 */
function logIncomingRequest(req, relevantHeaders, requestBody) {
  logger.info('🚀 API Request Incoming', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    path: req.path,
    ip: req.ip,
    headers: relevantHeaders,
    query: Object.keys(req.query).length > 0 ? req.query : undefined,
    body: requestBody,
    userAgent: req.get('User-Agent')
  });
}

/**
 * Configura interceptores para capturar la respuesta
 * @param {Object} res - Response object
 * @returns {Object} Objeto con responseBody y responseHeaders
 */
function setupResponseInterceptors(res) {
  const originalSend = res.send;
  const originalJson = res.json;

  let responseBody = null;
  let responseHeaders = null;

  // Interceptar res.send()
  res.send = function(data) {
    responseBody = data;
    responseHeaders = res.getHeaders();
    return originalSend.call(this, data);
  };

  // Interceptar res.json()
  res.json = function(data) {
    responseBody = data;
    responseHeaders = res.getHeaders();
    return originalJson.call(this, data);
  };

  return { responseBody, responseHeaders };
}

/**
 * Registra la respuesta saliente
 * @param {Object} req - Request object
 * @param {Object} res - Response object
 * @param {number} startTime - Tiempo de inicio de la petición
 * @param {*} responseBody - Body de la respuesta
 * @param {Object} responseHeaders - Headers de la respuesta
 */
function logOutgoingResponse({ req, res, startTime, responseBody, responseHeaders }) {
  const duration = Date.now() - startTime;

  logger.info('✅ API Response Outgoing', {
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    path: req.path,
    statusCode: res.statusCode,
    duration: `${duration}ms`,
    headers: responseHeaders,
    body: responseBody
  });
}

/**
 * Maneja el evento 'finish' de la respuesta
 * @param {Object} req - Request object
 * @param {Object} res - Response object
 * @param {number} startTime - Tiempo de inicio
 * @param {Object} relevantHeaders - Headers relevantes
 * @param {*} requestBody - Request body
 * @param {*} responseBody - Response body
 * @param {Object} responseHeaders - Response headers
 */
const {
  logDetailedResponse,
  logApplicationErrors,
  logApiRequestSummary
} = require('./responseHelpers');

async function handleResponseFinish({ req, res, startTime, relevantHeaders, requestBody, responseBody, responseHeaders }) {
  const endTime = Date.now();
  const responseTime = endTime - startTime;

  logDetailedResponse({ req, res, responseTime, relevantHeaders, requestBody, responseHeaders, responseBody });
  await logApplicationErrors({ req, res, relevantHeaders, requestBody, responseHeaders, responseBody });
  logApiRequestSummary({ req, res, responseTime, requestBody, responseBody });
}

module.exports = {
    shouldExcludePath,
    captureRequestBody,
    captureRelevantHeaders,
    logIncomingRequest,
    setupResponseInterceptors,
    logOutgoingResponse,
    handleResponseFinish
};

const { Credentials } = require('../models');
const logger = require('../utils/logger');

/**
 * Middleware de autenticación para tokens temporales
 * Solo permite acceso a endpoints básicos: /versions, /credentials, /details
 */
const {
  buildMissingTokenResponse,
  buildInvalidTokenResponse,
  buildForbiddenEndpointResponse,
  setRequestCredentials
} = require('./tempTokenAuth/authFlowHelpers');
const {
  extractTempToken,
  findTempCredentials,
  isTempTokenPathAllowed
} = require('./tempTokenAuth/authHelpers');

const tempTokenAuth = async (req, res, next) => {
    try {
        const token = extractTempToken(req);

        if (!token) {
            const response = buildMissingTokenResponse(req);
            return res.status(response.status).json(response.json);
        }

        const credentials = await findTempCredentials(token);

        if (!credentials) {
            const response = buildInvalidTokenResponse(req, token);
            return res.status(response.status).json(response.json);
        }

        if (!isTempTokenPathAllowed(req.originalUrl)) {
            const response = buildForbiddenEndpointResponse(req, token);
            return res.status(response.status).json(response.json);
        }

        setRequestCredentials(req, credentials);
        next();
    } catch (error) {
        logger.error('Temp token auth error:', error);

        res.status(500).json({
            status_code: 2000,
            status_message: 'Internal server error during authentication',
            timestamp: new Date().toISOString()
        });
    }
};

module.exports = tempTokenAuth;

